from datetime import datetime


class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate

    def fee(self, entry: datetime, exit: datetime) -> float:
        # Total duration in seconds
        duration_seconds = (exit - entry).total_seconds()
        if duration_seconds < 0:
            raise ValueError("exit must not be before entry")

        duration_minutes = duration_seconds / 60.0

        # Stays longer than 24 hours: flat penalty
        if duration_minutes > 24 * 60:
            return 200.00

        # Stays of at most 15 minutes are free
        if duration_minutes <= 15:
            return 0.00

        # Every started hour is charged as a full hour
        hours = duration_seconds / 3600.0
        started_hours = int(hours)
        if hours > started_hours:
            started_hours += 1

        fee = started_hours * self.hourly_rate
        return round(fee, 2)
